function localCSV(name,headers,rows){const csv='\ufeff'+[headers,...rows].map(row=>row.map(cell=>'"'+String(cell??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='DEMO-'+name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
