actions['user-detail']=b=>{const p=f4.userMeta.find(p=>p.id===b.dataset.id);showSheet(p.name,'จัดการข้อมูลและบทบาทในชุดตัวอย่าง',`<form id="user4" class="stack">${field('ชื่อที่ใช้ลงงาน',input('user-name',p.name,'text','required'))}${field('ชื่อเต็ม',input('user-full',p.fullName))}${field('บทบาท',select('user-role',state.role==='superadmin'?['Staff','Admin','Superadmin']:['Staff','Admin'],p.role))}<label class="row"><input type="checkbox" name="user-active" ${p.active?'checked':''}>เปิดใช้งาน</label></form>`,button('ตรวจการเปลี่ยนแปลง','review-user4','shield','primary',`data-id="${p.id}"`));};
actions['review-user4']=b=>{const form=$('#user4');if(!form.reportValidity())return;const v=new FormData(form);f4.pendingUser={id:b.dataset.id,name:v.get('user-name'),fullName:v.get('user-full'),role:v.get('user-role'),active:v.get('user-active')==='on'};showSheet('ยืนยันการเปลี่ยนแปลง','ข้อมูลและบทบาทตัวอย่าง',note(`${escapeHTML(v.get('user-name'))} · ${escapeHTML(v.get('user-role'))}`,'','shield'),button('ยืนยันตัวอย่าง','save-user4','check','primary'));};
actions['save-user4']=()=>{const p=f4.userMeta.find(p=>p.id===f4.pendingUser.id);Object.assign(p,f4.pendingUser);closeSheet();refresh();notify('ปรับข้อมูลและบทบาทตัวอย่างแล้ว');};
