document.addEventListener('input',event=>{const el=event.target;if(el.name==='task-query'){f4.taskQuery=el.value;$('#task-results').innerHTML=taskOptions();}if(el.name==='model-rotation')$('.device-model')?.style.setProperty('--rotation',el.value+'deg');});
document.addEventListener('change',event=>{const el=event.target;
 if(el.classList.contains('combo-check'))updateComboCount();
 if(el.dataset.log){if(el.checked)f4.selected.add(el.dataset.log);else f4.selected.delete(el.dataset.log);refresh();}
 if(el.id==='select-log-page'){const shown=filteredLogs().slice((f4.page-1)*f4.pageSize,f4.page*f4.pageSize);shown.forEach(l=>el.checked?f4.selected.add(l.id):f4.selected.delete(l.id));refresh();}
 if(['log-start','log-end'].includes(el.name)){f4[el.name==='log-start'?'start':'end']=el.value;f4.page=1;refresh();}
 if(el.name==='analytics-person'){f4.person=el.value;refresh();}
 if(el.name==='staff-sort'){f4.staffSort=el.value;refresh();}
 if(el.name==='export4-year'){state.year=el.value;applyPeriod('fiscal');refresh();}
 if(el.name==='export4-scope'){f4.exportScope=el.value;}
 if(el.name==='broadcast-audience')f4.broadcastAudience=el.value;
 if(el.name==='push-scenario')f4.pushStatus=el.value;
 if(el.name==='registry-state'){f4.registryState=el.value;notify('แสดงรายการตามสถานะที่เลือก');}
 if(el.name==='review-role'&&state.role==='staff'){state.staff=people[0].id;refresh();}
});
