function registryCards(){const rows=state.devices.filter(d=>(f4.registryState==='all'||(f4.registryState==='active'?d.active:!d.active))&&(state.location==='ทั้งหมด'||d.location===state.location)&&(`${d.id} ${d.name} ${d.barcode}`.toLowerCase().includes(state.search.toLowerCase()))).sort((a,b)=>a.order-b.order);return rows.length?`<div class="grid cols-4 equipment-grid">${rows.map(d=>`<article class="panel device-card"><div class="equipment-art">${icon(d.type)}</div><div class="row between"><h3>${escapeHTML(d.name)}</h3>${tag(!d.active?'หยุดใช้งาน':d.borrowed?'กำลังยืม':'พร้อมใช้',d.active&&!d.borrowed?'green':d.borrowed?'amber':'')}</div><small>${d.id} · ${d.location}</small><div class="row between"><small>${d.barcode} · #${d.itemNo}</small></div><div class="row between"><small>ลำดับ ${d.order}</small>${miniButton('แก้ไข','edit-device','edit',`data-id="${d.id}"`)}</div></article>`).join('')}</div>`:panel('',`<div class="empty-state"><h3>ไม่มีอุปกรณ์ตรงตัวกรอง</h3><p>เปลี่ยนสังกัด สถานะ หรือคำค้น</p></div>`);}
renderers.equipment=()=>heading('EQUIPMENT REGISTRY','จัดการอุปกรณ์','ชื่อ สังกัด ลำดับ และสถานะ ใช้ข้อมูลชุดเดียวกับบันทึกด่วน',button('เพิ่มอุปกรณ์','add-device','plus','primary'))+`<div class="toolbar glass">${search('ค้นหาชื่อ รหัส หรือ Barcode')}<label>สังกัด ${select('location',['ทั้งหมด','ชั้น 3','Finn Space'],state.location)}</label></div>`+registryCards();
renderers.users=function(){const rows=f4.userMeta.filter(p=>(p.name+' '+p.fullName+' '+p.email).toLowerCase().includes(state.search.toLowerCase()));return heading('PEOPLE & ACCESS','จัดการผู้ใช้','ชื่อที่ลงงาน การเข้าใช้งาน และคำขอเพิ่มสิทธิ์')+`<div class="toolbar glass">${segment('users-tab',[['active','สมาชิก'],['pending','รออนุมัติ'],...(state.role==='superadmin'?[['requests','คำขอเพิ่มสิทธิ์']]:[])],state.usersTab)}${search('ค้นหาชื่อหรือบัญชี')}</div>`+(state.usersTab==='active'?tablePanel(['ชื่อที่ใช้ลงงาน','ชื่อเต็ม / บัญชี','บทบาท','สถานะ',''],rows.map(p=>[escapeHTML(p.name),`${escapeHTML(p.fullName)}<small>${escapeHTML(p.email)}</small>`,tag(p.role),tag(p.active?'ใช้งานอยู่':'ปิดใช้งาน',p.active?'green':''),miniButton('จัดการ','user-detail','edit',`data-id="${p.id}"`)]),'สมาชิกในทีม'):panel(state.usersTab==='pending'?'คำขอเข้าใช้งาน':'คำขอเพิ่มสิทธิ์',(state.usersTab==='pending'?f4.pendingMembers:f4.roleRequests).filter(p=>p.status==='pending').map(p=>`<div class="list-row"><span class="avatar">${icon('person')}</span><div class="grow"><strong>${p.name}</strong><small>${p.reason}</small></div>${miniButton('พิจารณา','member-review','shield',`data-id="${p.id}" data-kind="${state.usersTab}"`)}</div>`).join('')||'<div class="empty-state"><h3>ไม่มีคำขอรอตรวจ</h3></div>'));};
actions['member-review']=b=>{const list=b.dataset.kind==='pending'?f4.pendingMembers:f4.roleRequests,p=list.find(p=>p.id===b.dataset.id);showSheet('พิจารณาคำขอ',p.name,`<div class="stack"><p>${p.reason}</p>${field('เหตุผลประกอบ','<textarea name="member-note" rows="3"></textarea>')}<div id="member-error" class="field-error"></div></div>`,miniButton('ไม่อนุมัติ','member-decide','close',`data-id="${p.id}" data-kind="${b.dataset.kind}" data-status="rejected"`)+button('อนุมัติตัวอย่าง','member-decide','shield','primary',`data-id="${p.id}" data-kind="${b.dataset.kind}" data-status="approved"`));};
actions['member-decide']=b=>{if(!ensureOnline())return;const reason=$('[name="member-note"]').value.trim();if(b.dataset.status==='rejected'&&!reason){$('#member-error').textContent='กรุณาระบุเหตุผลที่ไม่อนุมัติ';return;}if(state.role==='staff'||(b.dataset.kind==='requests'&&state.role!=='superadmin')){notify('บทบาทนี้พิจารณาคำขอไม่ได้');return;}const list=b.dataset.kind==='pending'?f4.pendingMembers:f4.roleRequests,p=list.find(p=>p.id===b.dataset.id);p.status=b.dataset.status;p.note=reason;closeSheet();refresh();notify('บันทึกผลพิจารณาตัวอย่างแล้ว');};
function templateEditor(id){const t=f4.templateRows.find(t=>t.id===id);f4.templateEditing=id||null;f4.templateDraft=t?[...t.items]:[];showSheet(t?'แก้ไขเทมเพลต':'สร้างเทมเพลต','กำหนดหัวข้อรอง เงื่อนไข และงานในชุด',`<form id="template4" class="stack">${field('ชื่อเทมเพลต *',input('tpl-name',t?.name||'','text','required'))}${field('รูปแบบ',select('tpl-kind',[['general','ทั่วไป'],['smart','Smart · อุปกรณ์ / ห้อง'],['combo','Combo · หลายงาน']],t?.kind||'general'))}${field('หัวข้อรอง',select('tpl-task',sourceMinorTasks,t?.minorTask||sourceMinorTasks[0]))}<p class="caption">หัวข้อหลักสัมพันธ์กับหัวข้อรองที่เลือก</p><label class="row"><input type="checkbox" name="tpl-recipient" ${t?.requireRecipient?'checked':''}>ต้องกรอกผู้รับบริการ</label><label class="row"><input type="checkbox" name="tpl-comment" ${t?.requireComment?'checked':''}>ต้องกรอกรายละเอียด</label><label class="row"><input type="checkbox" name="tpl-checkbox" ${t?.checkbox!==false?'checked':''}>Combo เลือกเฉพาะงานที่ทำจริงได้</label><label class="row"><input type="checkbox" name="tpl-active" ${t?.active!==false?'checked':''}>เปิดใช้งานในบันทึกด่วน</label><div id="template-items4">${templateItemFields()}</div>${miniButton('เพิ่มงานในชุด','tpl-add-item','plus','type="button"')}<div id="template-error4" class="field-error"></div></form>`,button('ตรวจและบันทึก','save-template4','check','primary'));$('#sheet').classList.add('sheet-wide');}
function templateItemFields(){return f4.templateDraft.map((t,i)=>`<div class="row" style="margin:8px 0"><input name="tpl-item-${i}" value="${escapeHTML(t)}" aria-label="งานในชุด ${i+1}" required><button type="button" class="icon-btn" data-action="tpl-remove-item" data-index="${i}" aria-label="ลบงานในชุด ${i+1}">${icon('close')}</button></div>`).join('');}
function stashTemplateItems(){f4.templateDraft=$$('[name^="tpl-item-"]').map(i=>i.value);}
renderers.templates=function(){return heading('QUICK LOG LIBRARY','บันทึกด่วนและ Combo','เทมเพลต เงื่อนไข และรายการงาน เชื่อมกับหน้าบันทึกด่วน',button('สร้างเทมเพลต','new-template','plus','primary'))+`<div class="toolbar glass">${search('ค้นหาเทมเพลต')}<small>${f4.templateRows.length} เทมเพลต</small></div><div class="grid cols-3">${f4.templateRows.filter(t=>t.name.includes(state.search)).map(t=>`<article class="panel template-card"><button class="icon-btn" data-action="edit-template4" data-id="${t.id}" aria-label="แก้ไข ${t.name}">${icon('more')}</button><span class="tile-icon">${icon(t.symbol)}</span><h3>${escapeHTML(t.name)}</h3><p>${escapeHTML(t.minorTask)}</p><div class="row between">${tag(t.kind==='combo'?t.items.length+' งาน · เลือกเอง':t.kind==='smart'?'Smart':'ทั่วไป')}${tag(t.active?'ใช้งาน':'หยุดใช้',t.active?'green':'')}</div><div class="row">${miniButton('ดูตัวอย่าง','template-run','bolt',`data-id="${t.id}"`)}</div></article>`).join('')}</div>`;};
actions['new-template']=()=>templateEditor();actions['edit-template4']=b=>templateEditor(b.dataset.id);
actions['tpl-add-item']=()=>{stashTemplateItems();f4.templateDraft.push('');$('#template-items4').innerHTML=templateItemFields();};
actions['tpl-remove-item']=b=>{stashTemplateItems();f4.templateDraft.splice(Number(b.dataset.index),1);$('#template-items4').innerHTML=templateItemFields();};
actions['save-template4']=()=>{const form=$('#template4');if(!form.reportValidity()||!ensureOnline())return;const v=new FormData(form);stashTemplateItems();if(v.get('tpl-kind')==='combo'&&!f4.templateDraft.filter(t=>t.trim()).length){$('#template-error4').textContent='Combo ต้องมีอย่างน้อย 1 งาน';return;}let t=f4.templateRows.find(t=>t.id===f4.templateEditing);if(!t){t={id:'TPL-LOCAL-'+Date.now(),symbol:'bolt',action:'generic-template'};f4.templateRows.push(t);}Object.assign(t,{name:v.get('tpl-name'),kind:v.get('tpl-kind'),minorTask:v.get('tpl-task'),requireRecipient:v.get('tpl-recipient')==='on',requireComment:v.get('tpl-comment')==='on',checkbox:v.get('tpl-checkbox')==='on',active:v.get('tpl-active')==='on',items:f4.templateDraft.filter(t=>t.trim())});closeSheet();refresh();notify('บันทึกเทมเพลตและอัปเดตบันทึกด่วนแล้ว');};
quickLogPanel=function(){const all=f4.templateRows.filter(t=>t.active),pages=Math.max(1,Math.ceil(all.length/6));f4.quickPage=Math.min(f4.quickPage,pages-1);return `<div class="quick-grid">${all.slice(f4.quickPage*6,f4.quickPage*6+6).map(t=>`<button class="quick-card" data-action="template-run" data-id="${t.id}"><span class="tile-icon">${icon(t.symbol)}</span><span><strong>${escapeHTML(t.name)}</strong><small>${t.kind==='combo'?t.items.length+' งาน · เลือกเฉพาะที่ทำ':t.kind==='smart'?'แสดงตามสถานะล่าสุด':t.requireComment?'ต้องมีรายละเอียด':'ตรวจรายการก่อนบันทึก'}</small></span></button>`).join('')}</div><div class="row between" style="margin-top:16px">${miniButton('ก่อนหน้า','quick-prev','back',f4.quickPage===0?'disabled':'')}<small>${f4.quickPage+1}/${pages}</small>${miniButton('ถัดไป','quick-next','chevron',f4.quickPage===pages-1?'disabled':'')}</div>`;};
actions['quick-prev']=()=>{f4.quickPage=Math.max(0,f4.quickPage-1);refresh();};actions['quick-next']=()=>{f4.quickPage++;refresh();};
actions['template-run']=b=>{const t=f4.templateRows.find(t=>t.id===b.dataset.id);f4.runningTemplate=t;if(t.kind==='combo'){comboDialog(t.action==='combo-software'?'software':'account');return;}if(t.action==='smart-room'){smartRoom(t.floor);return;}if(t.action==='equipment-picker'){equipmentPicker('headphones','ทั้งหมด');return;}if(t.action==='power-picker'){equipmentPicker('plug','ทั้งหมด');return;}if(t.action==='usb-picker'){equipmentPicker('usb','ทั้งหมด');return;}commentDialog(t.minorTask);};
const originalComboDialog=comboDialog;
comboDialog=function(kind){originalComboDialog(kind);const t=f4.runningTemplate;if(t?.kind==='combo'){$('#sheet-title').textContent=t.name;const labels=$$('.combo-item');labels.forEach(e=>e.remove());const anchor=$('[name="combo-recipient"]').closest('.field').parentElement;anchor.insertAdjacentHTML('beforebegin',t.items.map((text,i)=>`<label class="combo-item"><input type="checkbox" class="combo-check" value="${i}" checked><span><strong>${escapeHTML(text)}</strong><small>${escapeHTML(t.minorTask)}</small></span></label>`).join(''));updateComboCount();}};
