actions['combo-review']=()=>{const items=$$('.combo-check:checked').map(c=>Number(c.value)),recipient=$('[name="combo-recipient"]').value.trim(),tasks=selectedComboTasks();if(!items.length||!recipient){$('#combo-error').textContent=!items.length?'เลือกอย่างน้อย 1 งาน':'ระบุผู้รับบริการ';return;}f4.recipient=recipient;showSheet('ตรวจรายการที่เลือก',`${items.length} จาก ${tasks.length} งาน · ${escapeHTML(recipient)}`,items.map(i=>`<div class="list-row">${icon('check')}<strong>${escapeHTML(tasks[i])}</strong></div>`).join(''),button('ยืนยัน '+items.length+' งาน','combo-save','check','primary',`data-items="${items.join(',')}"`));};
actions['combo-save']=b=>{if(!ensureOnline())return;const items=b.dataset.items.split(',').map(Number),tasks=selectedComboTasks(),batch='BATCH-'+Date.now();items.forEach(i=>state.logs.unshift({id:batch+'-'+i,date:f4.date,time:f4.time,person:currentPerson().name,task:tasks[i],detail:'Combo · '+batch,recipient:f4.recipient,status:'บันทึกแล้ว',batch}));closeSheet();refresh();notify('บันทึก '+items.length+' งานที่เลือกแล้ว');};
function examEditor(id){const e=state.exams.find(e=>e.id===id);f4.examEditing=id||null;const [start,end]=(e?.time||'17:00–18:30').split('–');showSheet(id?'แก้ไขรอบสอบ':'เพิ่มรอบสอบ DL','เวลาเริ่ม–จบเก็บชัดเจน รอบเดิมไม่เปลี่ยนตามชื่อช่วง',`<form id="exam4" class="form-grid">${field('วันที่',input('exam-date',e?.date||'2026-11-24','date','required'),true)}${field('ช่วงเวลา',select('exam4-slot',[['custom','กำหนดเอง / เวลาเดิม'],['morning','เช้า 09:00–10:30'],['afternoon','บ่าย 13:30–15:00'],['evening','เย็น 17:00–18:30']],id?'custom':'evening'),true)}${field('เวลาเริ่ม',input('exam-start',start,'time','required'))}${field('เวลาสิ้นสุด',input('exam-end',end,'time','required'))}${field('ประเภทผู้เข้าสอบ',select('exam-type',['นักศึกษา','บุคลากร'],e?.examType||'นักศึกษา'))}${field('จำนวนคนต่อรอบ',input('exam-count',e?.count||75,'number','min="1" required'))}<div id="exam-rooms" class="full note">${icon('door')}<span>ห้อง 406 + 407 · มากกว่า 40 คน</span></div><label class="row full"><input type="checkbox" name="exam-cem" ${e?.rooms?.includes('CEM')?'checked':''}>ใช้ CEM เพิ่ม</label>${field('ผู้คุมสอบ 3 คน','<div class="stack" style="gap:8px">'+[0,1,2].map((i)=>select('exam-proctor-'+i,people.map(p=>[p.id,p.name]),people.find(p=>p.name===e?.proctors[i])?.id||people[[0,2,4][i]].id)).join('')+'</div>',true)}${field('หมายเหตุ / ผู้สอบแทน',`<textarea name="exam-notes" rows="2">${escapeHTML(e?.notes||'')}</textarea>`,true)}<label class="row full"><input type="checkbox" name="exam-active" ${e?.active!==false?'checked':''}>เปิดใช้งานรอบนี้</label><div id="exam-validation" class="full field-error"></div></form>`,button('ตรวจและบันทึก','save-exam4','check','primary'));$('#sheet').classList.add('sheet-wide');}
actions['add-exam']=()=>examEditor();actions['edit-exam4']=b=>examEditor(b.dataset.id);
actions['exam-day']=b=>{const date=`${state.examYear}-${String(state.examMonth).padStart(2,'0')}-${String(b.dataset.day).padStart(2,'0')}`;showSheet('รอบสอบ '+date,'ตรวจผู้คุมสอบ สถานที่ และสถานะ',state.exams.filter(e=>e.date===date).map(e=>`<div class="list-row"><div class="grow"><strong>${e.time} · ${e.count} คน</strong><small>${e.rooms} · ${e.examType||'นักศึกษา'}</small><small>${e.proctors.join(', ')}</small></div>${miniButton('แก้ไข','edit-exam4','edit',`data-id="${e.id}"`)}</div>`).join(''));};
actions['save-exam4']=()=>{const form=$('#exam4');if(!form.reportValidity()||!ensureOnline())return;const v=new FormData(form),start=v.get('exam-start'),end=v.get('exam-end'),proctors=[0,1,2].map(i=>v.get('exam-proctor-'+i));const fail=text=>$('#exam-validation').textContent=text;if(start>=end){fail('เวลาสิ้นสุดต้องอยู่หลังเวลาเริ่ม');return;}if(new Set(proctors).size!==3){fail('เลือกผู้คุมสอบ 3 คนที่ไม่ซ้ำกัน');return;}const date=v.get('exam-date');if(state.exams.some(e=>e.id!==f4.examEditing&&e.date===date&&e.active!==false&&e.time.split('–')[0]<end&&e.time.split('–')[1]>start)){fail('ห้องหรือเวลาชนกับรอบเดิม');return;}let row=state.exams.find(e=>e.id===f4.examEditing);if(!row){row={id:'DL-LOCAL-'+Date.now()};state.exams.push(row);}const count=Number(v.get('exam-count'));Object.assign(row,{date,day:Number(date.slice(-2)),time:start+'–'+end,count,rooms:(count>40?'406 + 407':'406')+(v.get('exam-cem')?' + CEM':''),proctors:proctors.map(id=>people.find(p=>p.id===id).name),notes:v.get('exam-notes'),examType:v.get('exam-type'),active:v.get('exam-active')==='on'});state.examMonth=Number(date.slice(5,7));state.examYear=Number(date.slice(0,4));closeSheet();refresh();notify('อัปเดตรอบสอบแล้ว');};
function classEditor(id){const row=f4.classes.find(r=>r.id===id);f4.classEditing=id||null;showSheet(id?'แก้ไขตารางเรียน':'เพิ่มตารางเรียน','ตรวจวัน เวลา ห้อง และผู้สอนก่อนบันทึก',`<form id="class4" class="form-grid">${field('วัน',select('class-day',['จันทร์','อังคาร','พุธ','พฤหัสบดี','ศุกร์'],row?.day||'จันทร์'))}${field('ห้อง',select('class-room',['401','402','406','407'],row?.room||'401'))}${field('เริ่ม',input('class-start',row?.start||'08:00','time','required'))}${field('สิ้นสุด',input('class-end',row?.end||'10:00','time','required'))}${field('วิชา / กิจกรรม',input('class-subject',row?.subject||'','text','required'),true)}${field('อาจารย์ผู้สอน',input('class-teacher',row?.teacher||''),true)}${field('หมายเหตุ',`<textarea name="class-note" rows="2">${escapeHTML(row?.note||'')}</textarea>`,true)}<label class="row full"><input type="checkbox" name="class-active" ${row?.active!==false?'checked':''}>เปิดใช้งาน</label><div id="class-error" class="full field-error"></div></form>`,button('ตรวจและบันทึก','save-class4','check','primary'));}
renderers.classrooms=function(){const rows=f4.classes.filter(r=>r.semester===f4.semester&&(state.room==='ทั้งหมด'||r.room===state.room));return heading('CLASSROOM SCHEDULE','ตารางเรียน','ตารางประจำสัปดาห์ รายละเอียดผู้สอน และสถานะการใช้งาน',miniButton('คัดลอกภาคเรียน','copy-classes4','layers')+button('เพิ่มตารางเรียน','add-class','plus','primary'))+`<div class="toolbar glass"><label>ภาคเรียน ${select('class-semester',['2/2569','1/2570','1/2569'],f4.semester)}</label><label>ห้อง ${select('room',['ทั้งหมด','401','402','406','407'],state.room)}</label>${segment('class-view',[['week','สัปดาห์','calendar'],['list','รายการ','file']],f4.classView)}</div>`+(f4.classView==='list'?tablePanel(['เลือก','วัน / เวลา','ห้อง','วิชา / ผู้สอน','สถานะ',''],rows.map(r=>[`<input type="checkbox" data-class="${r.id}" aria-label="เลือกชั้นเรียน ${r.id}" ${f4.classSelection.has(r.id)?'checked':''}>`,`${r.day}<small>${r.start}–${r.end}</small>`,r.room,`<strong>${escapeHTML(r.subject)}</strong><small>${escapeHTML(r.teacher)}</small>`,tag(r.active?'เปิดใช้':'ปิดใช้',r.active?'green':''),miniButton('แก้ไข','edit-class4','edit',`data-id="${r.id}"`)]),'ตารางเรียน'):panel('สัปดาห์ประจำภาคเรียน',`<div class="table-scroll"><div class="schedule-grid"><div class="schedule-head">เวลา</div>${['จันทร์','อังคาร','พุธ','พฤหัสบดี','ศุกร์'].map(d=>`<div class="schedule-head">${d}</div>`).join('')}${['08:00','10:00','13:00','15:00','17:00'].map(time=>`<div><small>${time}</small></div>${['จันทร์','อังคาร','พุธ','พฤหัสบดี','ศุกร์'].map(day=>`<div>${rows.filter(r=>r.day===day&&r.start>=time&&r.start<(time==='17:00'?'23:59':String(Number(time.slice(0,2))+2).padStart(2,'0')+':00')).map(r=>`<button class="class-event blue" data-action="edit-class4" data-id="${r.id}"><strong>${escapeHTML(r.subject)}</strong><small>${r.start}–${r.end} · ${r.room}</small><small>${escapeHTML(r.teacher)}</small></button>`).join('')}</div>`).join('')}`).join('')}</div></div>`))+`${f4.classSelection.size?`<div class="worklog-selection glass"><strong>${f4.classSelection.size} รายการ</strong>${miniButton('เปิดใช้งาน','bulk-class4','check','data-active="true"')}${miniButton('ปิดใช้งาน','bulk-class4','close','data-active="false"')}</div>`:''}`;};
actions['add-class']=()=>classEditor();actions['edit-class4']=b=>classEditor(b.dataset.id);
actions['save-class4']=()=>{const form=$('#class4');if(!form.reportValidity()||!ensureOnline())return;const v=new FormData(form),start=v.get('class-start'),end=v.get('class-end');if(start>=end){$('#class-error').textContent='เวลาสิ้นสุดต้องอยู่หลังเวลาเริ่ม';return;}if(f4.classes.some(r=>r.id!==f4.classEditing&&r.semester===f4.semester&&r.active&&r.day===v.get('class-day')&&r.room===v.get('class-room')&&r.start<end&&r.end>start)){$('#class-error').textContent='ห้องและเวลาซ้อนกับชั้นเรียนเดิม';return;}let row=f4.classes.find(r=>r.id===f4.classEditing);if(!row){row={id:'CLASS-LOCAL-'+Date.now()};f4.classes.push(row);}Object.assign(row,{day:v.get('class-day'),start,end,room:v.get('class-room'),subject:v.get('class-subject'),teacher:v.get('class-teacher'),note:v.get('class-note'),active:v.get('class-active')==='on',semester:f4.semester});closeSheet();refresh();notify('อัปเดตตารางเรียนแล้ว');};
actions['bulk-class4']=b=>{f4.classes.filter(r=>f4.classSelection.has(r.id)).forEach(r=>r.active=b.dataset.active==='true');f4.classSelection.clear();refresh();notify('เปลี่ยนสถานะชั้นเรียนที่เลือกแล้ว');};
