actions['preview-copy4']=()=>{f4.copyTarget=$('[name="copy-semester"]').value;const rows=f4.classes.filter(r=>r.semester===f4.semester);showSheet('ตรวจตารางที่จะคัดลอก',`${f4.semester} → ${f4.copyTarget}`,note(`${rows.length} รายการ · ตรวจข้อมูลซ้ำก่อนเพิ่ม`,'','layers'),button('ยืนยันคัดลอกตัวอย่าง','confirm-copy4','check','primary'));};
actions['confirm-copy4']=()=>{if(!ensureOnline())return;let added=0;f4.classes.filter(r=>r.semester===f4.semester).forEach(r=>{if(!f4.classes.some(t=>t.semester===f4.copyTarget&&t.day===r.day&&t.start===r.start&&t.room===r.room)){f4.classes.push({...r,id:'CLASS-COPY-'+Date.now()+'-'+added,semester:f4.copyTarget});added++;}});f4.semester=f4.copyTarget;closeSheet();refresh();notify('คัดลอก '+added+' รายการ โดยข้ามข้อมูลซ้ำ');};
