function staffRows4(){const factor=(state.year==='2570'?1:state.year==='2569'?1.35:.8)*(state.month==='all'?1:.22);return people.map((p,i)=>({...p,count:Math.round(p.count*factor),volume:Math.round(p.count*factor),versatility:5+(i*3)%6,consistency:70+(i*7)%25,peakHandling:10+(i*5)%20,documentation:68+(i*11)%30,combo:4+(i*7)%18})).filter(p=>p.name.toLowerCase().includes(state.search.toLowerCase())).sort((a,b)=>(b[f4.staffSort]||b.count)-(a[f4.staffSort]||a.count));}
