renderers.staff=function(){if(f4.staffView==='single')return singleStaff4();const rows=staffRows4();return heading('TEAM PLANNING','Staff Analytics','ข้อมูลจำลองสำหรับวางแผนกำลังคน ตามปีงบและเดือนที่เลือก')+fyToolbar()+`<div class="toolbar glass">${segment('staff-view',[['list','รายการ','file'],['single','ทีละคน','person']],f4.staffView)}${search('ค้นหาเจ้าหน้าที่')}<label>เรียงตาม ${select('staff-sort',[['count','จำนวนงาน'],['versatility','ความหลากหลาย'],['consistency','ความสม่ำเสมอ'],['peakHandling','งานวันหนาแน่น'],['documentation','รายละเอียด'],['combo','การใช้ Combo']],f4.staffSort)}</label><span class="spacer"></span>${miniButton('CSV','staff-csv','download')}</div>`+metrics([['รายการงาน',rows.reduce((n,p)=>n+p.count,0),'ตามตัวกรองที่เลือก','file'],['เจ้าหน้าที่',rows.length,'ในผลการค้นหา','users'],['ช่วงเวลา',state.month==='all'?'ทั้งปี':months[Number(state.month)],'ปีงบ '+state.year,'calendar']])+`<div class="grid cols-2">${panel('การกระจายงานรายคน',ranks(rows.map(p=>[escapeHTML(p.name),p.count]),Math.max(1,...rows.map(p=>p.count))))}${panel('ขอบเขตตัวชี้วัด',note('ความถี่ ความหลากหลาย ความสม่ำเสมอ งานในวันหนาแน่น รายละเอียด และการใช้ Combo เป็นคำอธิบายบันทึก ไม่ใช่คะแนนคุณภาพงาน','','help'))}</div><div style="margin-top:20px">`+tablePanel(['เจ้าหน้าที่','จำนวนงาน','ความหลากหลาย','สม่ำเสมอ','มีรายละเอียด','Combo',''],rows.map(p=>[escapeHTML(p.name),p.count,p.versatility,p.consistency+'%',p.documentation+'%',p.combo,miniButton('ดูรายคน','staff-detail4','person',`data-id="${p.id}"`)]),'รูปแบบบันทึกของทีม')+'</div>';};
